const fiches = [
  { titre: "Array.prototype.map", tags: "tableau transformation" },
  { titre: "document.querySelector", tags: "dom selection" },
  { titre: "npm ci", tags: "node dependances" }
];

function normaliser(texte) {
  return texte.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
}

function rechercher(terme) {
  const recherche = normaliser(terme.trim());
  return fiches.filter((fiche) =>
    normaliser(`${fiche.titre} ${fiche.tags}`).includes(recherche)
  );
}

champ.addEventListener("input", (event) => {
  const resultats = rechercher(event.target.value);
  liste.innerHTML = resultats.length
    ? resultats.map((fiche) => `<li>${fiche.titre}</li>`).join("")
    : "<li>Aucun résultat</li>";
});

