"use strict";
const fiches = [{ titre: "JavaScript map", tags: "tableau" }, { titre: "HTML", tags: "web" }];
const champ = document.querySelector("#recherche");
const liste = document.querySelector("#resultats");
const etat = document.querySelector("#etat");
const normaliser = texte => texte.normalize("NFD").replace(/[\u0300-\u036f]/g, "").toLowerCase();
function afficher() {
  const terme = normaliser(champ.value.trim());
  const visibles = fiches.filter(f => normaliser(`${f.titre} ${f.tags}`).includes(terme));
  liste.replaceChildren(...visibles.map(f => { const li = document.createElement("li"); li.textContent = f.titre; return li; }));
  etat.textContent = visibles.length ? `${visibles.length} résultat(s)` : "Aucun résultat";
}
champ.addEventListener("input", afficher);
afficher();
